components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; }
.ds-button-primary:hover:enabled { background: var(--primary-hover, #103f46); }
.ds-button-primary:active:enabled { background: var(--primary-pressed, #082f33); }
.ds-button-primary:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
.ds-button-primary:disabled { color: var(--action-disabled-label, #103f46); background: var(--action-disabled, #a9b88f); border-color: transparent; opacity: 1; cursor: not-allowed; }
@media (forced-colors: active) { .ds-button-primary:disabled { color: GrayText; opacity: 1; } }
.ds-button-primary svg { display: inline-block; flex: 0 0 16px; vertical-align: middle; }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; color: var(--foreground, #103f46); border-color: var(--input, #103f46); background: transparent; }
.ds-button-secondary:hover:enabled { color: var(--muted-text, #103f46); background: var(--muted, #a8d5ba); }
.ds-button-secondary:active:enabled { color: var(--reflection-ink, #103f46); background: var(--reflection-sage, #a9b88f); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
.ds-button-secondary:disabled { color: var(--action-disabled-label, #103f46); background: var(--action-disabled, #a9b88f); border-color: transparent; opacity: 1; cursor: not-allowed; }
@media (forced-colors: active) { .ds-button-secondary:disabled { color: GrayText; opacity: 1; } }

.ds-button-text { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; color: var(--reflection-link, #126f73); background: transparent; border-color: transparent; text-decoration: underline; text-underline-offset: 4px; }
.ds-button-text:hover:enabled { color: var(--muted-text, #103f46); background: var(--muted, #a8d5ba); }
.ds-button-text:active:enabled { color: var(--reflection-ink, #103f46); background: var(--reflection-sage, #a9b88f); }
.ds-button-text:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
.ds-button-text:disabled { color: var(--action-disabled-label, #103f46); background: var(--action-disabled, #a9b88f); border-color: transparent; opacity: 1; cursor: not-allowed; }
@media (forced-colors: active) { .ds-button-text:disabled { color: GrayText; opacity: 1; } }

.ds-button-danger { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; color: var(--destructive-foreground, #103f46); background: var(--destructive-button, #f28b7b); }
.ds-button-danger:hover:enabled { background: var(--reflection-butter, #f1d27b); }
.ds-button-danger:active:enabled { background: var(--reflection-sage, #a9b88f); }
.ds-button-danger:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
.ds-button-danger:disabled { color: var(--action-disabled-label, #103f46); background: var(--action-disabled, #a9b88f); border-color: transparent; opacity: 1; cursor: not-allowed; }
@media (forced-colors: active) { .ds-button-danger:disabled { color: GrayText; opacity: 1; } }

.ds-text-input { width: 100%; min-width: 0; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); color: var(--foreground, #103f46); }
.ds-text-input label { display: block; font-size: 16px; font-weight: 600; line-height: 24px; }
.ds-text-input input { box-sizing: border-box; display: block; width: 100%; min-height: 48px; margin: 8px 0 16px; padding: 12px 16px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; color: var(--foreground, #103f46); background: var(--background, #f7f3e8); border: 1px solid var(--input, #103f46); border-radius: var(--radius-lg, 0.75rem); }
.ds-text-input input::placeholder { color: var(--muted-foreground, #103f46); }
.ds-text-input input:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; border-color: var(--ring, #126f73); outline-color: var(--ring, #126f73); outline-offset: 2px; }
.ds-text-input input:disabled { opacity: 0.5; pointer-events: none; }
@media (forced-colors: active) { .ds-text-input input:disabled { color: GrayText; opacity: 1; } }

.ds-reflection-field { width: 100%; min-width: 0; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); color: var(--foreground, #103f46); }
.ds-reflection-field label { display: block; font-size: 16px; font-weight: 600; line-height: 24px; }
.ds-reflection-field textarea { box-sizing: border-box; display: block; width: 100%; min-height: 48px; margin: 8px 0 16px; padding: 12px 16px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; color: var(--foreground, #103f46); background: var(--background, #f7f3e8); border: 1px solid var(--input, #103f46); border-radius: var(--radius-lg, 0.75rem); min-height: 96px; resize: vertical; margin-bottom: 8px; }
.ds-reflection-field textarea::placeholder { color: var(--muted-foreground, #103f46); }
.ds-reflection-field textarea:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; border-color: var(--ring, #126f73); outline-color: var(--ring, #126f73); outline-offset: 2px; }
.ds-reflection-field textarea:disabled { opacity: 0.5; pointer-events: none; }
@media (forced-colors: active) { .ds-reflection-field textarea:disabled { color: GrayText; opacity: 1; } }
.ds-reflection-field p { margin: 0; color: var(--muted-foreground, #103f46); font-size: 12px; font-weight: 500; line-height: 18px; }

.ds-reading-nav { box-sizing: border-box; display: flex; width: 100%; max-width: 440px; gap: 4px; margin: 0; padding: 3px; border: 1px solid var(--input, #103f46); border-radius: var(--radius-full, 9999px); }
.ds-reading-nav button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; color: var(--foreground, #103f46); border-color: var(--input, #103f46); background: transparent; flex: 1; min-width: 0; padding-inline: 12px; color: var(--foreground, #103f46); background: transparent; border-color: transparent; }
.ds-reading-nav button:active:enabled { color: var(--reflection-ink, #103f46); background: var(--reflection-sage, #a9b88f); }
.ds-reading-nav button:hover:enabled { color: var(--muted-text, #103f46); background: var(--muted, #a8d5ba); }
.ds-reading-nav button[aria-current="page"] { color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border-color: var(--primary, #126f73); }
.ds-reading-nav button[aria-current="page"]:hover:enabled { color: var(--primary-foreground, #f7f3e8); background: var(--primary-hover, #103f46); }
.ds-reading-nav button:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
@media (forced-colors: active) { .ds-reading-nav button[aria-current="page"], .ds-reading-nav button[aria-current="page"]:hover:enabled { color: HighlightText; background: Highlight; border-color: Highlight; forced-color-adjust: none; } }

.ds-reflection-card { font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); background: var(--card, #f7f3e8); color: var(--card-foreground, #103f46); border: 1px solid var(--border-subtle, color-mix(in srgb, #103f46 25%, transparent)); border-radius: var(--radius-3xl, 24px); box-shadow: var(--shadow-sm, none); padding: var(--space-6, 1.5rem); border-block: 1px solid var(--border, #103f46); margin: 0; padding: var(--space-6, 1.5rem); }
.ds-reflection-card h2 { margin: 0; font-family: var(--font-serif, "Newsreader", Georgia, ui-serif, serif); font-size: 28px; font-weight: 400; line-height: 1.2143; margin-bottom: 8px; }
.ds-reflection-card p { margin: 0 0 20px; color: var(--muted-foreground, #103f46); font-size: 14px; line-height: 20px; max-width: 48ch; }

.ds-history { width: 100%; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); color: var(--foreground, #103f46); list-style: none; padding: 0; margin: 16px 0 0; border-top: 1px solid var(--border, #103f46); }
.ds-history li { border-bottom: 1px solid var(--border, #103f46); display: flex; align-items: center; gap: 16px; padding: 12px 4px; }
.ds-history li > div { flex: 1; min-width: 0; }
.ds-history time { line-height: 1.5; font-variant-numeric: tabular-nums; display: block; color: var(--muted-foreground, #103f46); font-size: 12px; }
.ds-history button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 11px 24px; font-family: var(--font-sans, "Figtree", ui-sans-serif, system-ui, sans-serif); font-size: 16px; line-height: 24px; font-weight: 600; color: var(--primary-foreground, #f7f3e8); background: var(--primary, #126f73); border: 1px solid transparent; border-radius: var(--radius-full, 9999px); cursor: pointer; width: 100%; padding-inline: 0; color: var(--foreground, #103f46); background: transparent; border: 0; text-align: left; overflow-wrap: anywhere; justify-content: space-between; gap: 16px; padding-block: 10px; font-family: var(--font-serif, "Newsreader", Georgia, ui-serif, serif); font-size: 22px; font-weight: 500; line-height: 24px; border-radius: 0; }
.ds-history button svg { display: inline-block; flex: 0 0 16px; vertical-align: middle; color: var(--muted-foreground, #103f46); }
.ds-history button:active:enabled { background: var(--primary-pressed, #082f33); }
.ds-history button:hover:enabled { color: var(--foreground, #103f46); background: transparent; }
.ds-history button:hover span { text-decoration: underline; text-underline-offset: 4px; }
.ds-history button:focus-visible { outline: 2px solid var(--foreground, #103f46); outline-offset: 4px; }
.ds-history button:disabled { color: var(--action-disabled-label, #103f46); background: var(--action-disabled, #a9b88f); border-color: transparent; opacity: 1; cursor: not-allowed; }
@media (forced-colors: active) { .ds-history button:disabled { color: GrayText; opacity: 1; } }
